function ProductManager({org,notify}:{org?:Org;notify:(x:string)=>void}){
 const empty={name:"",category:"Frutas y verduras",price:"",stock:"",description:"",unit_measure:"unidad",unit_quantity:"1",sku:""};
 const [list,setList]=useState<any[]>([]),[open,setOpen]=useState(false),[saving,setSaving]=useState(false),[importing,setImporting]=useState(false),[image,setImage]=useState<File|null>(null),[preview,setPreview]=useState(""),[editingId,setEditingId]=useState<string|null>(null),[f,setF]=useState(empty);
 const load=()=>{if(org)supabase.from("catalog_products").select("*").eq("organization_id",org.id).order("created_at",{ascending:false}).then(({data})=>setList(data||[]))};useEffect(load,[org]);
 const presentation=(p:any)=>p.unit_measure==="unidad"?`${p.unit_quantity||1} unidad${Number(p.unit_quantity||1)>1?"es":""}`:`${p.unit_quantity||1} ${p.unit_measure}${Number(p.unit_quantity||1)>1?"s":""}`;
 async function uploadImage(){if(!image||!org)return "";const ext=image.name.split(".").pop()?.toLowerCase()||"jpg",path=`${org.id}/${crypto.randomUUID()}.${ext}`;const {error}=await supabase.storage.from("product-images").upload(path,image,{upsert:false});if(error)throw error;return supabase.storage.from("product-images").getPublicUrl(path).data.publicUrl}
 async function save(){
  const missing=[] as string[];
  if(!org){notify("Tu cuenta todavÃ­a no tiene una empresa vinculada. Completa o espera la aprobaciÃ³n del registro de empresa.");return}
  if(!f.name.trim())missing.push("nombre del producto");
  if(f.price.trim()===""||!Number.isFinite(Number(f.price))||Number(f.price)<=0)missing.push("precio mayor que cero");
  if(f.stock.trim()===""||!Number.isInteger(Number(f.stock))||Number(f.stock)<0)missing.push("inventario (puede ser 0)");
  if(f.unit_quantity.trim()===""||!Number.isFinite(Number(f.unit_quantity))||Number(f.unit_quantity)<=0)missing.push("cantidad por presentaciÃ³n");
  if(missing.length){notify(`Revisa: ${missing.join(", ")}.`);return}
  setSaving(true);try{const uploadedImage=await uploadImage(),payload={...f,name:f.name.trim(),sku:f.sku.trim(),description:f.description.trim(),organization_id:org!.id,price:Number(f.price),stock:Number(f.stock),unit_quantity:Number(f.unit_quantity),...(uploadedImage?{image_url:uploadedImage}:{})};const {data,error}=editingId?await supabase.rpc("update_catalog_product",{target_product:editingId,payload}):await supabase.rpc("save_catalog_product",{payload:{...payload,image_url:uploadedImage}});if(error)throw error;setList(editingId?list.map(p=>p.id===editingId?data:p):[data,...list]);setF(empty);setImage(null);setPreview("");setEditingId(null);setOpen(false);notify(editingId?"Producto actualizado correctamente.":"Producto guardado correctamente.")}catch(e:any){notify(`No pudimos guardar el producto: ${e.message||"revisa los datos"}`)}finally{setSaving(false)}}
 async function importCsv(file:File){
  if(!org)return;setImporting(true);
  try{
   const text=(await file.text()).replace(/^\uFEFF/,""),lines=text.split(/\r?\n/).filter(line=>line.trim()),delimiter=lines[0].includes("\t")?"\t":lines[0].includes(";")?";":",";
   const normalize=(value:string)=>value.trim().toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"");
   const headers=lines[0].split(delimiter).map(normalize),validUnits:Record<string,string>={unidad:"unidad",unidades:"unidad",libra:"libra",libras:"libra",lb:"libra",gramo:"gramo",gramos:"gramo",gr:"gramo",kilogramo:"kilogramo",kilogramos:"kilogramo",kilo:"kilogramo",kilos:"kilogramo",kg:"kilogramo"};
   let ok=0;const failures:string[]=[];
   for(const [index,line] of lines.slice(1).entries()){
    const values=line.split(delimiter).map(x=>x.trim()),row=Object.fromEntries(headers.map((h,i)=>[h,values[i]||""]));
    let unitRaw=normalize(row.unidad||row.unit_measure||"unidad"),quantityRaw=row.cantidad||row.unit_quantity||"1";
    if(!validUnits[unitRaw]&&validUnits[normalize(quantityRaw)]&&Number.isFinite(Number(unitRaw))){const swapped=quantityRaw;quantityRaw=unitRaw;unitRaw=normalize(swapped)}
    const name=row.nombre||row.name,price=Number(row.precio||row.price),stock=Number(row.inventario||row.stock||0),unit=validUnits[unitRaw],quantity=Number(quantityRaw);
    if(!name||!Number.isFinite(price)||price<=0||!Number.isInteger(stock)||stock<0||!unit||!Number.isFinite(quantity)||quantity<=0){failures.push(`fila ${index+2}`);continue}
    const {error}=await supabase.rpc("save_catalog_product",{payload:{organization_id:org.id,name,category:row.categoria||row.category||"Despensa",description:row.descripcion||row.description||"",price,stock,unit_measure:unit,unit_quantity:quantity,sku:row.sku||"",image_url:row.imagen||row.image_url||""}});
    if(error)failures.push(`fila ${index+2}: ${error.message}`);else ok++
   }
   notify(failures.length?`${ok} productos importados. No se pudieron importar ${failures.length} (${failures.slice(0,3).join(", ")}).`:`${ok} productos importados correctamente.`);load()
  }catch(e:any){notify(`No pudimos importar el archivo: ${e.message}`)}finally{setImporting(false)}
 }
 function chooseImage(file?:File){if(!file)return;if(!["image/jpeg","image/png","image/webp"].includes(file.type)||file.size>5*1024*1024){notify("La imagen debe ser JPG, PNG o WEBP y pesar mÃ¡ximo 5 MB.");return}setImage(file);setPreview(URL.createObjectURL(file))}
 function editProduct(p:any){setEditingId(p.id);setF({name:p.name||"",category:p.category||"Frutas y verduras",price:String(p.price??""),stock:String(p.stock??""),description:p.description||"",unit_measure:p.unit_measure||"unidad",unit_quantity:String(p.unit_quantity??1),sku:p.sku||""});setImage(null);setPreview(p.image_url||"");setOpen(true);window.scrollTo({top:0,behavior:"smooth"})}
 useEffect(()=>{const articles=Array.from(document.querySelectorAll<HTMLElement>(".product-admin-grid article"));const cleanups:(()=>void)[]=[];articles.forEach((article,index)=>{const product=list[index],edit=article.querySelector<HTMLButtonElement>("button:not(.product-active-toggle)");if(!product||!edit)return;const editHandler=()=>editProduct(product);edit.addEventListener("click",editHandler);cleanups.push(()=>edit.removeEventListener("click",editHandler));let toggle=article.querySelector<HTMLButtonElement>(".product-active-toggle");if(!toggle){toggle=document.createElement("button");toggle.className="product-active-toggle";article.appendChild(toggle)}toggle.textContent=product.is_active?"Activo":"Inactivo";toggle.setAttribute("aria-pressed",String(product.is_active));toggle.title=product.is_active?"Inactivar producto":"Activar producto";const toggleHandler=async()=>{toggle!.disabled=true;const next=!product.is_active,{error}=await supabase.from("catalog_products").update({is_active:next,updated_at:new Date().toISOString()}).eq("id",product.id).eq("organization_id",org!.id);toggle!.disabled=false;if(error){notify(`No se pudo cambiar el estado: ${error.message}`);return}setList(current=>current.map(p=>p.id===product.id?{...p,is_active:next}:p));notify(next?"Producto activado en la tienda.":"Producto inactivado y oculto de la tienda.")};toggle.addEventListener("click",toggleHandler);cleanups.push(()=>toggle?.removeEventListener("click",toggleHandler))});return()=>cleanups.forEach(clean=>clean())},[list,org]);
 return <div className="admin-card"><div className="table-head"><div><h2>Productos y precios</h2><p>Administra fotografÃ­a, presentaciÃ³n, precio e inventario de tu catÃ¡logo.</p></div><div className="catalog-actions"><label className="import-button">{importing?"Importandoâ€¦":"â‡§ Importar CSV"}<input type="file" accept=".csv,text/csv" disabled={importing} onChange={e=>e.target.files?.[0]&&importCsv(e.target.files[0])}/></label><button className="primary" onClick={()=>setOpen(!open)}>ï¼‹ Nuevo producto</button></div></div><div className="csv-help"><b>ImportaciÃ³n masiva:</b> usa columnas nombre, categoria, precio, inventario, unidad, cantidad, sku, descripcion e imagen.</div>{open&&<div className="product-editor"><label className="image-upload">{preview?<img src={preview} alt="Vista previa"/>:<span>ðŸ“·<b>Cargar fotografÃ­a</b><small>JPG, PNG o WEBP Â· mÃ¡ximo 5 MB</small></span>}<input type="file" accept="image/jpeg,image/png,image/webp" onChange={e=>chooseImage(e.target.files?.[0])}/></label><div className="product-form form-grid"><label>Nombre del producto *<input required value={f.name} onChange={e=>setF({...f,name:e.target.value})}/></label><label>SKU / referencia<input value={f.sku} onChange={e=>setF({...f,sku:e.target.value})}/></label><label>CategorÃ­a *<select required value={f.category} onChange={e=>setF({...f,category:e.target.value})}><option>Frutas y verduras</option><option>Carnes</option><option>Huevos y lÃ¡cteos</option><option>Despensa</option><option>Bebidas</option><option>Aseo y hogar</option></select></label><label>Precio de esta presentaciÃ³n *<input required type="number" min="0.01" step="0.01" value={f.price} onChange={e=>setF({...f,price:e.target.value})}/></label><label>Unidad de medida *<select required value={f.unit_measure} onChange={e=>setF({...f,unit_measure:e.target.value})}><option value="unidad">Unidad</option><option value="libra">Libra</option><option value="gramo">Gramo</option><option value="kilogramo">Kilogramo</option></select></label><label>Cantidad por presentaciÃ³n *<input required type="number" min="0.001" step="0.001" value={f.unit_quantity} onChange={e=>setF({...f,unit_quantity:e.target.value})}/><small>Ej.: 1 kilogramo, 500 gramos o 6 unidades.</small></label><label>Inventario disponible *<input required type="number" min="0" step="1" value={f.stock} onChange={e=>setF({...f,stock:e.target.value})}/><small>Puedes escribir 0 si todavÃ­a no tienes existencias.</small></label><label className="full">DescripciÃ³n<input value={f.description} onChange={e=>setF({...f,description:e.target.value})}/></label><button type="button" className="primary full" disabled={saving} onClick={save}>{saving?"Guardandoâ€¦":"Guardar producto"}</button></div></div>}<div className="product-admin-grid">{list.length?list.map(p=><article key={p.id}>{p.image_url?<img className="admin-product-image" src={p.image_url} alt={p.name}/>:<span>ðŸ“¦</span>}<div><b>{p.name}</b><small>{p.category} Â· {presentation(p)} Â· inventario: {p.stock}</small></div><strong>{money(Number(p.price))}</strong><button>Editar</button></article>):<div className="table-empty">AÃºn no has registrado productos.</div>}</div></div>
}
function CityManager({notify}:{notify:(x:string)=>void}){const [cities,setCities]=useState(["Barranquilla","Soledad"]),[city,setCity]=useState("");async function add(){if(!city)return;const {error}=await supabase.from("service_cities").insert({name:city});if(!error)setCities([...cities,city]);setCity("");notify(error?"No fue posible agregar la ciudad.":"Ciudad habilitada para entregas.")}return <div className="admin-card"><div className="table-head"><div><h2>Ciudades de cobertura</h2><p>Define dÃ³nde pueden comprar los clientes.</p></div></div><div className="city-add"><input placeholder="Nueva ciudad" value={city} onChange={e=>setCity(e.target.value)}/><button className="primary" onClick={add}>Agregar ciudad</button></div>{cities.map(c=><div className="provider-row" key={c}><span>ðŸ“</span><div><b>{c}</b><small>Disponible para pedidos</small></div><em className="status active">Activa</em></div>)}</div>}

